package com.citacloud.app.services; import com.citacloud.app.models.*; import com.citacloud.app.repositories.*; import org.springframework.stereotype.Service; import java.math.*; import java.util.*;
@Service public class SignosVitalesService {private final SignosVitalesRepository repo;private final PacienteRepository pacientes;public SignosVitalesService(SignosVitalesRepository r,PacienteRepository p){repo=r;pacientes=p;}public SignosVitales registrar(UUID empresa,UUID paciente,BigDecimal peso,BigDecimal altura,BigDecimal temp,Integer sistolica,Integer diastolica){pacientes.findByIdAndEmpresaId(paciente,empresa).orElseThrow(()->new IllegalArgumentException("Paciente no encontrado para esta empresa."));if(peso==null||altura==null||peso.signum()<=0||altura.signum()<=0)throw new IllegalArgumentException("Peso y altura válidos son obligatorios.");SignosVitales s=new SignosVitales();s.setEmpresaId(empresa);s.setPacienteId(paciente);s.setPeso(peso);s.setAltura(altura);s.setTemperatura(temp);s.setPresionSistolica(sistolica);s.setPresionDiastolica(diastolica);s.setImc(peso.divide(altura.multiply(altura),2,RoundingMode.HALF_UP));return repo.save(s);}}
